import{_ as t,o,c as d,a2 as a}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"ADOFAIMacro","description":"","frontmatter":{"title":"ADOFAIMacro","order":13},"headers":[],"relativePath":"mods/adofai-macro.md","filePath":"mods/adofai-macro.md","lastUpdated":1786957039000}'),r={name:"mods/adofai-macro.md"};function i(n,e,l,s,c,u){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="adofaimacro" tabindex="-1">ADOFAIMacro <a class="header-anchor" href="#adofaimacro" aria-label="Permalink to &quot;ADOFAIMacro&quot;">​</a></h1><blockquote><p>A UnityModManager (UMM) Mod for <em>A Dance of Fire and Ice</em> that provides more <strong>stable, adjustable, and filterable</strong> auto-input capabilities, covering scenarios from &quot;direct judgment triggering&quot; to &quot;system-level key simulation&quot;.</p><p>Project: <a href="https://github.com/adofaiex/ADOFAIMacro" target="_blank" rel="noreferrer">https://github.com/adofaiex/ADOFAIMacro</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Auto-trigger</strong>: parses chart floor timestamps, sends keys with high-precision timing on a worker thread</li><li><strong>Trigger modes</strong>: <ul><li><strong>Judgment trigger</strong> (<code>SimulateKeyPress = false</code>): worker thread counts → main thread <code>controller.Hit()</code></li><li><strong>Key simulation</strong> (<code>SimulateKeyPress = true</code>): worker thread calls <code>SendKey()</code> to simulate system-level key input</li></ul></li><li><strong>Macro key modes</strong>: <ul><li><strong>Simple rotation</strong> (<code>EnableTechniqueSimulation = false</code>): <code>MacroKeys</code> list cycles, with <code>_pendingKey</code> anti-overlap</li><li><strong>Technique simulation</strong> (<code>EnableTechniqueSimulation = true</code>): left/right hand alternation, configurable keys and order, BPM slicing, long-press handling, same-key correction</li></ul></li><li><strong>Per-level technique config</strong>: save independent technique parameters per level, auto-load on entry; supports per-floor interval overrides</li><li><strong>Time offset fine-tuning</strong>: millisecond-level offset, real-time adjustment with <code>Ctrl + Left/Right</code> / <code>Left/Right</code> in-game</li><li><strong>Key filter system</strong>: blacklist/whitelist mode, sync (KeyCode bitmap) and async (VK code array) independent filtering</li><li><strong>SkyHook async input</strong>: <code>NtUserInjectKeyboard</code> and other low-level injection paths, for high-frequency / complex environments</li><li><strong>Death key</strong>: configurable post-death key and trigger delay (SkyHook mode only)</li><li><strong>Multilingual UI</strong>: Chinese / English</li></ul><h2 id="operating-modes" tabindex="-1">Operating Modes <a class="header-anchor" href="#operating-modes" aria-label="Permalink to &quot;Operating Modes&quot;">​</a></h2><h3 id="direct-hit-mode-simulatekeypress-false" tabindex="-1">Direct Hit Mode (<code>SimulateKeyPress = false</code>) <a class="header-anchor" href="#direct-hit-mode-simulatekeypress-false" aria-label="Permalink to &quot;Direct Hit Mode (`SimulateKeyPress = false`)&quot;">​</a></h3><p>Macro triggers directly hit game logic. Short chain, controllable latency — suitable for pure macro judgment scenarios.</p><h3 id="key-simulation-mode-simulatekeypress-true" tabindex="-1">Key Simulation Mode (<code>SimulateKeyPress = true</code>) <a class="header-anchor" href="#key-simulation-mode-simulatekeypress-true" aria-label="Permalink to &quot;Key Simulation Mode (`SimulateKeyPress = true`)&quot;">​</a></h3><p>Converts macro triggers to system-level key input. Options:</p><ul><li><strong>SendInput path</strong> (compatibility-first)</li><li><strong>SkyHook path</strong> (lower-level, for complex / high-frequency environments)</li></ul><h3 id="skyhook-inputmode" tabindex="-1">SkyHook + InputMode <a class="header-anchor" href="#skyhook-inputmode" aria-label="Permalink to &quot;SkyHook + InputMode&quot;">​</a></h3><p>When <code>SkyHookMode = true</code>, you can select the input mode: <code>Auto</code> (auto-select), <code>NtUserInjectKeyboard</code> (low-level injection), <code>NtUserSendInput</code> (intermediate path), <code>SendInput</code> (standard, best compatibility). Start with <code>Auto</code> and switch if conflicts arise.</p><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>UnityModManager installed and working</li><li>ADOFAI can load Mods via UMM</li></ul><h3 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h3><ol><li>Compile the project to get <code>ADOFAIMacro.dll</code> (and related dependencies)</li><li>Place in the <code>Mods/ADOFAIMacro</code> directory: <ul><li><code>ADOFAIMacro.dll</code></li><li><code>Newtonsoft.Json.dll</code> (if not in the game directory)</li><li><code>Localization/</code> folder (with <code>zh-CN.json</code>, <code>en-US.json</code>)</li><li>Native DLLs (e.g. <code>InputSystem.dll</code>, <code>TechniqueSimulator.dll</code>)</li></ul></li><li>Launch the game and enable <code>ADOFAIMacro</code> in the UMM panel</li></ol><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><code>Macro</code></td><td>Master macro toggle</td></tr><tr><td><code>MacroKeys</code></td><td>Macro key sequence, comma-separated (e.g. <code>D,F,J,K</code>)</td></tr><tr><td><code>SimulateKeyPress</code></td><td>Use system key simulation instead of direct Hit</td></tr><tr><td><code>SkyHookMode</code></td><td>Use SkyHook path for key simulation</td></tr><tr><td><code>InputMode</code></td><td>Auto / NtInject / NtSendInput / SendInput</td></tr><tr><td><code>TimeOffset</code></td><td>Macro trigger time offset (-100 ~ 100 ms)</td></tr><tr><td><code>EnableKeyAdjust</code></td><td>Allow <code>Ctrl + Arrow keys</code> adjustment in-game</td></tr><tr><td><code>AdjustStep</code></td><td>Step per hotkey adjustment (0.1 ~ 10)</td></tr><tr><td><code>EnableArrowTimeAdjust</code></td><td>Allow Left/Right keys for quick delay adjustment</td></tr><tr><td><code>HighPrecisionAsync</code></td><td>Experimental high-precision async toggle</td></tr><tr><td><code>EnableDeathKey</code> / <code>DeathKeyDelay</code> / <code>DeathKeyInput</code></td><td>Post-death auto key (requires SkyHook mode)</td></tr><tr><td><code>EnableKeyFilter</code> / <code>FilterMode</code> / <code>FilteredKeys</code> / <code>FilteredAsyncKeys</code></td><td>Key filtering (0=blacklist, 1=whitelist)</td></tr></tbody></table><p>Key strings support <code>A-Z</code>, <code>0-9</code>, <code>F1-F12</code>, <code>SPACE</code>, <code>ENTER</code>, <code>ESC</code>, <code>CTRL</code>, <code>ALT</code>, arrow keys, and hex virtual key codes (e.g. <code>0x41</code>).</p><h2 id="runtime-hotkeys" tabindex="-1">Runtime Hotkeys <a class="header-anchor" href="#runtime-hotkeys" aria-label="Permalink to &quot;Runtime Hotkeys&quot;">​</a></h2><ul><li><strong>Ctrl + Left/Right arrow</strong>: adjust offset by <code>AdjustStep</code></li><li><strong>Left/Right arrow</strong>: fine-tune delay directly (controlled by <code>EnableArrowTimeAdjust</code>)</li></ul><h2 id="recommended-configurations" tabindex="-1">Recommended Configurations <a class="header-anchor" href="#recommended-configurations" aria-label="Permalink to &quot;Recommended Configurations&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Recommendation</th></tr></thead><tbody><tr><td>Stability (beginner)</td><td><code>SimulateKeyPress = false</code>, <code>TimeOffset = 0</code> start, fine-tune gradually</td></tr><tr><td>Compatibility (multi-software)</td><td><code>SimulateKeyPress = true</code>, <code>SkyHookMode = false</code>, SendInput path, enable <code>EnableKeyFilter</code> if needed</td></tr><tr><td>High-frequency (advanced)</td><td><code>SimulateKeyPress = true</code>, <code>SkyHookMode = true</code>, <code>InputMode = Auto</code> start, then fine-tune <code>TimeOffset</code> and <code>AdjustStep</code></td></tr></tbody></table><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li><strong>Macro on but no response?</strong> Check in order: enabled in UMM, <code>Macro</code> is on, <code>MacroKeys</code> format is correct, try switching <code>SkyHookMode</code> / <code>InputMode</code></li><li><strong>Intermittent triggers / missed keys?</strong> Adjust <code>TimeOffset</code> (1ms steps); try <code>SkyHookMode</code> for high-frequency; enable <code>EnableKeyFilter</code> to block conflicts</li><li><strong>Death key not working?</strong> Confirm <code>SkyHookMode</code> is on, <code>EnableDeathKey</code> is enabled, <code>DeathKeyInput</code> is a valid key name or code</li></ul>',26)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
